module BeachFoodTruck #(\n    parameter N = 5,\n    parameter DATA_WIDTH = 8,\n    parameter IDX_WIDTH = 3\n)(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [IDX_WIDTH-1:0] addr,\n    input wire [DATA_WIDTH-1:0] data_in,\n    input wire wr_en,\n    output reg [IDX_WIDTH-1:0] optimal_pos,\n    output reg done\n);\n\n// Hut memory declaration\nreg [DATA_WIDTH-1:0] hut_mem [0:N-1];\n\n// State machine parameters\nlocalparam [1:0] IDLE     = 2'd0;\nlocalparam [1:0] COMPUTE  = 2'd1;\nlocalparam [1:0] DONE_ST  = 2'd2;\n\nreg [1:0] state;\nreg [11:0] total_sum;\n\n// Combinational diff calculations\nwire [12:0] diff [0:4];\nwire [11:0] prefix0 = 12'd0;\nwire [11:0] prefix1 = hut_mem[0];\nwire [11:0] prefix2 = hut_mem[0] + hut_mem[1];\nwire [11:0] prefix3 = hut_mem[0] + hut_mem[1] + hut_mem[2];\nwire [11:0] prefix4 = hut_mem[0] + hut_mem[1] + hut_mem[2] + hut_mem[3];\n\n// Diff calculation functions\nfunction automatic [12:0] calc_diff(input [11:0] prefix, input [7:0] hut_val, input [11:0] total);\n    reg [12:0] tmp_val, abs_val;\n    begin\n        tmp_val = (prefix << 1) + hut_val - total;\n        abs_val = tmp_val[12] ? -tmp_val : tmp_val;\n        calc_diff = (abs_val >= {12'd0, hut_val[0]}) ? (abs_val - {12'd0, hut_val[0]}) : 13'd0;\n    end\nendfunction\n\nassign diff[0] = calc_diff(prefix0, hut_mem[0], total_sum);\nassign diff[1] = calc_diff(prefix1, hut_mem[1], total_sum);\nassign diff[2] = calc_diff(prefix2, hut_mem[2], total_sum);\nassign diff[3] = calc_diff(prefix3, hut_mem[3], total_sum);\nassign diff[4] = calc_diff(prefix4, hut_mem[4], total_sum);\n\n// Minimum diff finding\nreg [IDX_WIDTH-1:0] min_idx;\n\nalways @(*) begin\n    min_idx = 3'd0;\n    if (diff[1] < diff[min_idx]) min_idx = 3'd1;\n    if (diff[2] < diff[min_idx]) min_idx = 3'd2;\n    if (diff[3] < diff[min_idx]) min_idx = 3'd3;\n    if (diff[4] < diff[min_idx]) min_idx = 3'd4;\nend\n\n// Main sequential logic\ninteger i;\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        // Initialize memory and regs\n        for (i = 0; i < N; i = i + 1)\n            hut_mem[i] <= 8'd0;\n        state <= IDLE;\n        optimal_pos <= 3'd0;\n        done <= 1'b0;\n    end else begin\n        // Memory write operation\n        if (wr_en) hut_mem[addr] <= data_in;\n\n        // State machine\n        case (state)\n            IDLE: begin\n                done <= 1'b1;\n                if (start) begin\n                    total_sum <= hut_mem[0] + hut_mem[1] + hut_mem[2] + hut_mem[3] + hut_mem[4];\n                    state <= COMPUTE;\n                    done <= 1'b0;\n                end\n            end\n\n            COMPUTE: begin\n                optimal_pos <= min_idx;\n                state <= DONE_ST;\n            end\n\n            DONE_ST: begin\n                done <= 1'b1;\n                state <= IDLE;\n            end\n\n            default: state <= IDLE;\n        endcase\n    end\nend\n\nendmodule